/**
 * Ingest GW's official terrain-area *footprints* (the die-cut base-plate outlines
 * with irregular "nub" edges where rubble spills past the plate) from the Combat
 * Patrol: Battlezone Armageddon Footprint Punchboard PDF, and graft those nubbed
 * outlines onto the catalog's area templates in `data/core/terrain-templates.json`.
 *
 * ## Why this is safe for the 1108 dimension-card keystones
 *
 * Every area piece's keystones are pinned to the template rectangle's *corners*
 * (`{kind:"vertex", index:0..3}`) and a keystone reads exactly one axis of that
 * vertex (x for a left/right edge, y for top/bottom — see `terrain/keystones.ts`).
 * We keep the measurement **exactly invariant** by:
 *
 *  1. Anchoring each extracted nubbed outline to the template's EXISTING base
 *     rectangle `(0,0)-(w,h)` (the plate the cards already measure to). Nubs
 *     extend beyond it (y<0, y>h); the plate edges stay at x∈{0,w}, y∈{0,h}, and
 *     the studded plate borders leave real vertices sitting exactly on those
 *     lines. A ≤5% per-axis snap reconciles PDF-measurement noise against the
 *     template dims; anything larger fails loud (bad base detection).
 *  2. Re-pointing each keystone from the old corner index to a new-polygon vertex
 *     that carries the *same* coordinate on the measured axis (x=0/w or y=0/h),
 *     so the printed distance is identical to 4 dp.
 *  3. Compensating every referencing placement by `position += R·M·(c_new−c_old)`
 *     — the centroid moved when the footprint changed, so this keeps the plate
 *     corners resolving to their original board positions (same math as
 *     `fix-corner-ruin.ts`).
 *
 * The gate: `keystoneMeasurements()` before vs after must match within 2e-4 for
 * every keystone, and every piece that does not reference an updated template
 * must resolve bit-identically. A clean dry run therefore guarantees a clean
 * `--write`.
 *
 * `area-trapezoid` is intentionally **held**: the only large irregular PDF shape
 * (an 11.9×8″ L/pentagon) has no clean base rectangle, so force-fitting it would
 * corrupt its corner keystones. It is reported for separate manual authoring.
 *
 * Only the numerical polygon coordinates land in the repo (footprint geometry is
 * fact, like a stat line); the PDF and its artwork never do — pass it by path
 * from the gitignored `_private/sources/`.
 *
 * Usage (from `tools/`):
 *   npx tsx src/ingest-terrain-footprints.ts            # dry run + report
 *   npx tsx src/ingest-terrain-footprints.ts --write    # apply after a clean dry run
 *   npx tsx src/ingest-terrain-footprints.ts --pdf <path>
 *
 * Requires poppler's `pdftocairo` on PATH (per CLAUDE.md's PDF rules).
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  footprintVertices,
  polygonCentroid,
  type Footprint,
  type Mirror,
  type TerrainLayout,
  type TerrainTemplate,
  type Vec2,
} from "./terrain/resolve.js";
import { keystoneMeasurements } from "./terrain/keystones.js";

const REPO_ROOT = join(new URL("../..", import.meta.url).pathname);
const CATALOG_PATH = join(REPO_ROOT, "data", "core", "terrain-templates.json");
const LAYOUTS_PATH = join(REPO_ROOT, "data", "core", "terrain-layouts.json");
const DEFAULT_PDF = join(REPO_ROOT, "_private", "sources", "armageddon-combat-patrol-footprints.pdf");

const PT_PER_INCH = 72;
/** Douglas-Peucker tolerance, inches — keeps nub silhouette, sheds flattening noise. */
const SIMPLIFY_TOL = 0.03;
/** A vertex within this of a base-plate edge line is snapped exactly onto it. */
const EDGE_SNAP = 0.05;
/** Keystone-distance drift allowed by the invariance gate (matches resolver rounding). */
const KEYSTONE_TOL = 2e-4;

/**
 * The four rectangular area templates and the PDF footprint each maps to.
 * `rotate90` marks the one printed in portrait (page-2 tall) that must become
 * landscape to match the template's width-along-x convention. `area-trapezoid`
 * is deliberately absent — it is held (see file header).
 */
interface FootprintMap {
  templateId: string;
  page: number;
  expect: { w: number; h: number };
  rotate90: boolean;
}
const FOOTPRINTS: FootprintMap[] = [
  { templateId: "area-large", page: 3, expect: { w: 11.5, h: 7 }, rotate90: false },
  { templateId: "area-long-line", page: 1, expect: { w: 10, h: 2.5 }, rotate90: false },
  { templateId: "area-short-line", page: 2, expect: { w: 6, h: 2 }, rotate90: false },
  { templateId: "area-medium", page: 2, expect: { w: 6, h: 4 }, rotate90: true },
];
const HELD = ["area-trapezoid"];

// ---------------------------------------------------------------------------
// SVG path extraction
// ---------------------------------------------------------------------------

/** Flatten one SVG path subpath (absolute M/L/C/Z) to a polyline in user units. */
function flattenSubpath(seq: string[]): Vec2[] {
  const pts: Vec2[] = [];
  let cur: Vec2 | null = null;
  let i = 0;
  const num = (k: number): number => Number(seq[k]);
  while (i < seq.length) {
    const t = seq[i];
    if (t === "M" || t === "L") {
      cur = { x: num(i + 1), y: num(i + 2) };
      pts.push(cur);
      i += 3;
    } else if (t === "C") {
      const p0 = cur ?? { x: num(i + 1), y: num(i + 2) };
      const p1 = { x: num(i + 1), y: num(i + 2) };
      const p2 = { x: num(i + 3), y: num(i + 4) };
      const p3 = { x: num(i + 5), y: num(i + 6) };
      for (let s = 1; s <= 8; s++) {
        const u = s / 8;
        const m = 1 - u;
        pts.push({
          x: m ** 3 * p0.x + 3 * m * m * u * p1.x + 3 * m * u * u * p2.x + u ** 3 * p3.x,
          y: m ** 3 * p0.y + 3 * m * m * u * p1.y + 3 * m * u * u * p2.y + u ** 3 * p3.y,
        });
      }
      cur = p3;
      i += 7;
    } else {
      i += 1; // Z or stray token
    }
  }
  return pts;
}

function bbox(pts: Vec2[]): { w: number; h: number; x0: number; y0: number; x1: number; y1: number } {
  const xs = pts.map((p) => p.x);
  const ys = pts.map((p) => p.y);
  const x0 = Math.min(...xs);
  const x1 = Math.max(...xs);
  const y0 = Math.min(...ys);
  const y1 = Math.max(...ys);
  return { w: x1 - x0, h: y1 - y0, x0, y0, x1, y1 };
}

/** True if an SVG stroke color string is GW's footprint green (G dominant). */
function isFootprintGreen(attrs: string): boolean {
  const m = attrs.match(/stroke="rgb\(([\d.]+)%,\s*([\d.]+)%,\s*([\d.]+)%\)"/);
  if (!m) return false;
  const [r, g, b] = [Number(m[1]), Number(m[2]), Number(m[3])];
  return g > 40 && g > r + 15 && g > b + 15;
}

/**
 * One candidate footprint on a page: the fragments of its green die-cut outline
 * (broken at the punch-out nicks), plus the whole-path bbox for selection. GW
 * prints the terrain-area footprint edge as a green stroke — that IS the
 * authoritative boundary.
 */
interface OutlineCandidate {
  fragments: Vec2[][];
  bboxIn: { w: number; h: number };
}

function footprintOutlines(svg: string): OutlineCandidate[] {
  const out: OutlineCandidate[] = [];
  for (const m of svg.matchAll(/<path([^>]*)\sd="([^"]+)"/g)) {
    const attrs = m[1];
    if (!isFootprintGreen(attrs)) continue;
    const seq = m[2].match(/[MLCZ]|-?\d*\.?\d+(?:e-?\d+)?/g);
    if (!seq) continue;
    const subs: string[][] = [];
    let cur: string[] = [];
    for (const tok of seq) {
      if (tok === "M" && cur.length) {
        subs.push(cur);
        cur = [];
      }
      cur.push(tok);
    }
    if (cur.length) subs.push(cur);
    const fragments = subs.map(flattenSubpath).filter((p) => p.length >= 2);
    if (!fragments.length) continue;
    const all = fragments.flat();
    const b = bbox(all);
    const minDimIn = Math.min(b.w, b.h) / PT_PER_INCH;
    const maxDimIn = Math.max(b.w, b.h) / PT_PER_INCH;
    if (minDimIn > 2 && maxDimIn < 15) {
      out.push({ fragments, bboxIn: { w: b.w / PT_PER_INCH, h: b.h / PT_PER_INCH } });
    }
  }
  return out;
}

/**
 * Concatenate the die-cut fragments into one closed ring in document order:
 * pdftocairo emits the green outline's fragments in boundary order (each `M`
 * resumes the boundary after a punch-out nick), so a straight bridge across each
 * gap recovers the true outline. (Greedy endpoint stitching, by contrast,
 * mis-jumps across the shape and self-intersects — the integrity check in
 * `extractFootprint` guards against any regression here.)
 */
function stitchRing(fragments: Vec2[][]): Vec2[] {
  return fragments.flat();
}

/** Signed polygon area (shoelace), inches². */
function signedArea(ring: Vec2[]): number {
  let a = 0;
  const n = ring.length;
  for (let i = 0; i < n; i++) {
    const p = ring[i];
    const q = ring[(i + 1) % n];
    a += p.x * q.y - q.x * p.y;
  }
  return a / 2;
}

/** Count crossings between non-adjacent edges of a closed ring. */
function selfIntersections(ring: Vec2[]): number {
  const n = ring.length;
  const ccw = (a: Vec2, b: Vec2, c: Vec2): number => (c.y - a.y) * (b.x - a.x) - (b.y - a.y) * (c.x - a.x);
  const cross = (a: Vec2, b: Vec2, c: Vec2, d: Vec2): boolean =>
    ccw(c, d, a) > 0 !== ccw(c, d, b) > 0 && ccw(a, b, c) > 0 !== ccw(a, b, d) > 0;
  let count = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (Math.abs(i - j) <= 1 || (i === 0 && j === n - 1)) continue;
      if (cross(ring[i], ring[(i + 1) % n], ring[j], ring[(j + 1) % n])) count++;
    }
  }
  return count;
}

// ---------------------------------------------------------------------------
// Geometry helpers
// ---------------------------------------------------------------------------

const round4 = (n: number): number => Math.round(n * 1e4) / 1e4;

function transpose(pts: Vec2[]): Vec2[] {
  // Portrait → landscape. A reflection is fine: the plate is anchored to the
  // template frame afterward and the nub orientation is verified visually.
  return pts.map((p) => ({ x: p.y, y: p.x }));
}

/** Perpendicular distance from p to segment a-b. */
function perpDist(p: Vec2, a: Vec2, b: Vec2): number {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) return Math.hypot(p.x - a.x, p.y - a.y);
  const t = ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2;
  const cx = a.x + t * dx;
  const cy = a.y + t * dy;
  return Math.hypot(p.x - cx, p.y - cy);
}

/** Douglas-Peucker on an open polyline. */
function rdp(pts: Vec2[], tol: number): Vec2[] {
  if (pts.length < 3) return pts.slice();
  let maxD = 0;
  let idx = 0;
  const a = pts[0];
  const b = pts[pts.length - 1];
  for (let i = 1; i < pts.length - 1; i++) {
    const d = perpDist(pts[i], a, b);
    if (d > maxD) {
      maxD = d;
      idx = i;
    }
  }
  if (maxD <= tol) return [a, b];
  const left = rdp(pts.slice(0, idx + 1), tol);
  const right = rdp(pts.slice(idx), tol);
  return left.slice(0, -1).concat(right);
}

/**
 * Detect a base-plate edge range on one axis: the offset `[t, t+dim]` where the
 * plate's two edges (studded borders) carry the most vertices. When the outline
 * is barely wider than the plate on this axis (nubs only on the other axis), the
 * bbox extent is the base and is returned directly.
 */
function detectBaseRange(vals: number[], dim: number): [number, number] {
  const lo = Math.min(...vals);
  const hi = Math.max(...vals);
  const near = (v: number): number => vals.reduce((n, x) => (Math.abs(x - v) < 0.06 ? n + 1 : n), 0);
  if (hi - lo <= dim) return [lo, hi]; // no room to inset — base spans the bbox
  let bestT = lo;
  let bestScore = -1;
  for (let t = lo; t <= hi - dim + 1e-9; t += 0.02) {
    const score = near(t) + near(t + dim);
    if (score > bestScore) {
      bestScore = score;
      bestT = t;
    }
  }
  return [bestT, bestT + dim];
}

/**
 * Extract one nubbed footprint polygon in the template's local frame: base plate
 * exactly at (0,0)-(w,h), nubs extending beyond. Returns the polygon points and
 * the four base-corner indices in `footprintVertices` order [(0,0),(w,0),(w,h),(0,h)].
 */
function extractFootprint(
  rawPts: Vec2[],
  map: FootprintMap,
): { points: Vec2[]; baseCornerIdx: number[]; report: string } {
  let pts = rawPts.map((p) => ({ x: p.x / PT_PER_INCH, y: p.y / PT_PER_INCH }));
  if (map.rotate90) pts = transpose(pts);

  const { w, h } = map.expect;

  // Detect the base rectangle on both axes (nubs may extend any edge), then
  // anchor it exactly onto the template's (0,0)-(w,h) frame so keystones that
  // measured the old rectangle corners stay exactly invariant. The per-axis snap
  // corrects sub-tolerance PDF-measurement noise; a large snap means the base
  // detection is unreliable and fails loud.
  const [xL, xR] = detectBaseRange(pts.map((p) => p.x), w);
  const [yT, yB] = detectBaseRange(pts.map((p) => p.y), h);
  const sx = w / (xR - xL);
  const sy = h / (yB - yT);
  if (sx < 0.9 || sx > 1.1 || sy < 0.9 || sy > 1.1) {
    throw new Error(
      `${map.templateId}: base-detect scale (${sx.toFixed(3)}, ${sy.toFixed(3)}) out of range; ` +
        `detected base ${(xR - xL).toFixed(2)}×${(yB - yT).toFixed(2)} vs template ${w}×${h}.`,
    );
  }
  pts = pts.map((p) => ({ x: (p.x - xL) * sx, y: (p.y - yT) * sy }));

  // Snap vertices sitting on a base-plate edge line exactly onto it, so the plate
  // corners carry exact x∈{0,w} / y∈{0,h} coordinates for keystone matching.
  const snap = (v: number, line: number): number => (Math.abs(v - line) < EDGE_SNAP ? line : v);
  pts = pts.map((p) => ({
    x: snap(snap(p.x, 0), w),
    y: snap(snap(p.y, 0), h),
  }));

  // Close the loop and drop consecutive duplicates (the raw fragments are dense).
  let loop = pts.slice();
  while (loop.length > 1 && Math.hypot(loop[0].x - loop[loop.length - 1].x, loop[0].y - loop[loop.length - 1].y) < 1e-6) {
    loop.pop();
  }
  const dense: Vec2[] = [];
  for (const p of loop) {
    const last = dense[dense.length - 1];
    if (!last || Math.hypot(last.x - p.x, last.y - p.y) > 1e-9) dense.push(p);
  }

  // Insert the four base-plate corners into the DENSE ring (before simplifying),
  // so they sit ~0.05″ from a real vertex. footprintVertices order is
  // [(0,0),(w,0),(w,h),(0,h)]; keystones remap to these exact local points so the
  // resolver reproduces the old corner's board position under any rotation/mirror
  // once the centroid shift is compensated.
  const corners: Vec2[] = [
    { x: 0, y: 0 },
    { x: w, y: 0 },
    { x: w, y: h },
    { x: 0, y: h },
  ];
  const withCorners = insertCorners(dense, corners, map.templateId);

  // Simplify each boundary arc BETWEEN consecutive corners separately, so the
  // corners always survive as arc endpoints (a whole-ring RDP would drop the
  // base-edge vertices around a nubbed corner).
  const cIdx = corners
    .map((c) => withCorners.findIndex((p) => p.x === c.x && p.y === c.y))
    .sort((a, b) => a - b);
  const n = withCorners.length;
  let ring: Vec2[] = [];
  for (let k = 0; k < cIdx.length; k++) {
    const start = cIdx[k];
    const end = cIdx[(k + 1) % cIdx.length];
    const arc: Vec2[] = [];
    for (let i = start; i !== end; i = (i + 1) % n) arc.push(withCorners[i]);
    arc.push(withCorners[end]);
    const simp = rdp(arc, SIMPLIFY_TOL).map((p) => ({
      x: round4(snap(snap(p.x, 0), w)),
      y: round4(snap(snap(p.y, 0), h)),
    }));
    ring.push(...simp.slice(0, -1)); // end corner starts the next arc
  }
  // Drop consecutive duplicates from rounding/snapping.
  ring = ring.filter((p, i) => {
    const prev = ring[(i - 1 + ring.length) % ring.length];
    return prev.x !== p.x || prev.y !== p.y;
  });
  const baseCornerIdx = corners.map((c) => {
    const i = ring.findIndex((p) => p.x === c.x && p.y === c.y);
    if (i < 0) throw new Error(`${map.templateId}: corner (${c.x},${c.y}) missing after simplify`);
    return i;
  });

  // Integrity: the outline must be a simple polygon that encloses the plate
  // (nubs only add area). A self-intersection or shrunken area means the
  // fragment order was wrong — refuse rather than write a malformed footprint.
  const xints = selfIntersections(ring);
  const areaIn = Math.abs(signedArea(ring));
  const baseArea = w * h;
  if (xints > 0) throw new Error(`${map.templateId}: outline self-intersects (${xints}) — bad fragment order.`);
  if (areaIn < baseArea * 0.95 || areaIn > baseArea * 1.3) {
    throw new Error(
      `${map.templateId}: outline area ${areaIn.toFixed(1)}″² implausible vs base ${baseArea.toFixed(1)}″².`,
    );
  }

  const nb = bbox(ring);
  const report =
    `${map.templateId.padEnd(16)} base ${w}×${h}  nubbed bbox ${nb.w.toFixed(2)}×${nb.h.toFixed(2)}  ` +
    `verts ${ring.length}  area ${areaIn.toFixed(1)}″²  (scale ${sx.toFixed(3)}/${sy.toFixed(3)})`;
  return { points: ring, baseCornerIdx, report };
}

/** Distance from `c` to the closest point on SEGMENT a→b, and the clamped t. */
function segDist(c: Vec2, a: Vec2, b: Vec2): { d: number; t: number } {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len2 = dx * dx + dy * dy;
  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((c.x - a.x) * dx + (c.y - a.y) * dy) / len2));
  return { d: Math.hypot(c.x - (a.x + t * dx), c.y - (a.y + t * dy)), t };
}

/**
 * Insert the base corners onto the ring's boundary at the genuinely nearest
 * segment (clamped distance, so a far parallel edge can't win), spliced in
 * descending (segment, t) order so earlier splices don't shift later indices.
 * Sequential insertion instead mis-orders corners near the same nub and
 * self-intersects.
 */
function insertCorners(ring: Vec2[], corners: Vec2[], id: string): Vec2[] {
  const plan: { seg: number; t: number; c: Vec2 }[] = [];
  for (const c of corners) {
    if (ring.some((p) => p.x === c.x && p.y === c.y)) continue;
    let seg = 0;
    let bestD = Infinity;
    let bestT = 0;
    for (let i = 0; i < ring.length; i++) {
      const { d, t } = segDist(c, ring[i], ring[(i + 1) % ring.length]);
      if (d < bestD) {
        bestD = d;
        seg = i;
        bestT = t;
      }
    }
    if (bestD > 0.2) {
      throw new Error(`${id}: base corner (${c.x},${c.y}) is ${bestD.toFixed(3)}″ off the boundary (nub-covered).`);
    }
    plan.push({ seg, t: bestT, c });
  }
  const out = ring.slice();
  plan.sort((a, b) => b.seg - a.seg || b.t - a.t);
  for (const { seg, c } of plan) out.splice(seg + 1, 0, { x: c.x, y: c.y });
  return out;
}

