// ---------------------------------------------------------------------------
// Orientation math (mirrors the resolver; same as fix-corner-ruin.ts)
// ---------------------------------------------------------------------------

function applyMirror(v: Vec2, m: Mirror): Vec2 {
  if (m === "horizontal") return { x: -v.x, y: v.y };
  if (m === "vertical") return { x: v.x, y: -v.y };
  return v;
}
function rotateCw(v: Vec2, deg: number): Vec2 {
  const r = (deg * Math.PI) / 180;
  const c = Math.cos(r);
  const s = Math.sin(r);
  return { x: c * v.x - s * v.y, y: s * v.x + c * v.y };
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function renderPageSvg(pdf: string, page: number): string {
  const dir = mkdtempSync(join(tmpdir(), "footprints-"));
  try {
    const base = join(dir, "page");
    execFileSync("pdftocairo", ["-svg", "-f", String(page), "-l", String(page), pdf, `${base}.svg`], {
      stdio: ["ignore", "ignore", "inherit"],
    });
    // pdftocairo may suffix; grab the produced .svg.
    const svgs = readdirSync(dir).filter((f) => f.endsWith(".svg"));
    if (!svgs.length) throw new Error(`pdftocairo produced no SVG for page ${page}`);
    return readFileSync(join(dir, svgs[0]), "utf8");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function selectOutline(candidates: OutlineCandidate[], map: FootprintMap): Vec2[] {
  const tw = map.rotate90 ? map.expect.h : map.expect.w;
  const th = map.rotate90 ? map.expect.w : map.expect.h;
  let best: OutlineCandidate | null = null;
  let bestScore = Infinity;
  for (const c of candidates) {
    const score = Math.abs(c.bboxIn.w - tw) + Math.abs(c.bboxIn.h - th);
    if (score < bestScore) {
      bestScore = score;
      best = c;
    }
  }
  if (!best) throw new Error(`${map.templateId}: no green outline found on page ${map.page}`);
  return stitchRing(best.fragments);
}

function main(): void {
  const argv = process.argv.slice(2);
  const write = argv.includes("--write");
  const pdfArg = argv.indexOf("--pdf");
  const pdf = pdfArg >= 0 ? argv[pdfArg + 1] : DEFAULT_PDF;

  const catalog = JSON.parse(readFileSync(CATALOG_PATH, "utf8")) as TerrainTemplate[];
  const layouts = JSON.parse(readFileSync(LAYOUTS_PATH, "utf8")) as TerrainLayout[];
  const byId = new Map(catalog.map((t) => [t.id, t]));

  // Ground-truth keystone measurements with the ORIGINAL catalog + keystones.
  const before = new Map(layouts.map((l) => [l.id, keystoneMeasurements(l, catalog)]));

  // --- extract + patch the four rectangle templates -------------------------
  const svgByPage = new Map<number, string>();
  const extracted = new Map<string, { points: Vec2[]; baseCornerIdx: number[]; delta: Vec2 }>();
  console.log("Extracted footprints:");
  for (const map of FOOTPRINTS) {
    if (!svgByPage.has(map.page)) svgByPage.set(map.page, renderPageSvg(pdf, map.page));
    const outlines = footprintOutlines(svgByPage.get(map.page)!);
    const raw = selectOutline(outlines, map);
    const { points, baseCornerIdx, report } = extractFootprint(raw, map);
    console.log(`  ${report}`);

    const tpl = byId.get(map.templateId);
    if (!tpl) throw new Error(`template ${map.templateId} not in catalog`);
    if (tpl.footprint.type !== "rectangle") {
      throw new Error(`${map.templateId}: expected a rectangle footprint to replace, got ${tpl.footprint.type}`);
    }
    const cOld = polygonCentroid(footprintVertices(tpl.footprint));
    const newFp: Footprint = { type: "polygon", points };
    const cNew = polygonCentroid(points);
    extracted.set(map.templateId, {
      points,
      baseCornerIdx,
      delta: { x: cNew.x - cOld.x, y: cNew.y - cOld.y },
    });
    tpl.footprint = newFp;
  }

  // --- compensate placements + remap keystones ------------------------------
  const updated = new Set(FOOTPRINTS.map((m) => m.templateId));
  let touchedPieces = 0;
  let remappedKeystones = 0;
  let skippedInline = 0;
  for (const layout of layouts) {
    for (const piece of layout.pieces ?? []) {
      if (!piece.template || !updated.has(piece.template)) continue;
      if (piece.footprint) {
        skippedInline++; // inline geometry: template edit doesn't reach it
        continue;
      }
      const { delta } = extracted.get(piece.template)!;
      const d = rotateCw(applyMirror(delta, piece.mirror ?? "none"), piece.rotation_degrees ?? 0);
      piece.position = { x: round4(piece.position.x + d.x), y: round4(piece.position.y + d.y) };
      touchedPieces++;

      const { baseCornerIdx } = extracted.get(piece.template)!;
      for (const k of piece.keystones ?? []) {
        // Vertex (corner) refs — the 1108 the cards pin to the plate corners —
        // remap to the same corner in the new polygon, so their printed distance
        // is bit-invariant (compensation keeps the corner's board position, and
        // the geometric twin-pairing reflection still lands on the same corner).
        // Face refs are left untouched: they measure the piece's extent, which is
        // now the nubbed footprint edge (an honest change, ≤ one nub), and face↔
        // face twin pairing is preserved without the pairing-breaking conversion.
        if (k.ref.kind !== "vertex") continue;
        const mapped = baseCornerIdx[k.ref.index];
        if (mapped === undefined) {
          throw new Error(`${layout.id}/${piece.id}: keystone corner ${k.ref.index} out of rectangle range`);
        }
        k.ref.index = mapped;
        remappedKeystones++;
      }
    }
  }

  // --- invariance gate ------------------------------------------------------
  // Vertex (corner) keystones must be bit-invariant; face keystones may move by
  // up to one nub (they now measure the nubbed footprint extent).
  const after = new Map(layouts.map((l) => [l.id, keystoneMeasurements(l, catalog)]));
  let maxVertexDelta = 0;
  let maxFaceDelta = 0;
  let failures = 0;
  for (const layout of layouts) {
    const b = before.get(layout.id)!;
    const a = after.get(layout.id)!;
    if (b.length !== a.length) {
      failures++;
      console.error(`  ✗ ${layout.id}: keystone count changed ${b.length}→${a.length}`);
      continue;
    }
    for (let i = 0; i < b.length; i++) {
      if (b[i].edge !== a[i].edge || b[i].piece_index !== a[i].piece_index) {
        failures++;
        console.error(`  ✗ ${layout.id}: keystone order/edge changed at ${i}`);
        continue;
      }
      const diff = Math.abs(b[i].distance - a[i].distance);
      if (b[i].ref.kind === "vertex") {
        maxVertexDelta = Math.max(maxVertexDelta, diff);
        if (diff > KEYSTONE_TOL) {
          failures++;
          console.error(
            `  ✗ ${layout.id} piece ${a[i].piece_id ?? a[i].piece_index} ${a[i].edge}: ` +
              `corner distance ${b[i].distance} → ${a[i].distance} (Δ${diff.toFixed(5)})`,
          );
        }
      } else {
        maxFaceDelta = Math.max(maxFaceDelta, diff);
        if (diff > 0.75) {
          failures++;
          console.error(
            `  ✗ ${layout.id} piece ${a[i].piece_id ?? a[i].piece_index} ${a[i].edge}: ` +
              `face distance moved ${diff.toFixed(3)}″ (> one nub) — check nub extent`,
          );
        }
      }
    }
  }

  console.log(
    `\nHeld (unchanged, surfaced for manual authoring): ${HELD.join(", ")}` +
      ` — the PDF's large irregular shape has no clean base rectangle.`,
  );
  console.log(
    `\n${touchedPieces} placements compensated, ${remappedKeystones} corner keystones remapped ` +
      `(${skippedInline} inline-baked pieces skipped).`,
  );
  console.log(
    `Corner keystone drift: ${maxVertexDelta.toExponential(2)} (tol ${KEYSTONE_TOL}); ` +
      `max face-extent shift: ${maxFaceDelta.toFixed(3)}″ (now measures the nubbed edge).`,
  );

  if (failures > 0) {
    console.error(`\nINGEST FAILED: ${failures} keystone-invariance violations; files NOT written.`);
    process.exit(1);
  }

  if (!write) {
    console.log("\nDry run OK. Re-run with --write to apply (validation via `npm run validate`).");
    return;
  }
  writeFileSync(CATALOG_PATH, `${JSON.stringify(catalog, null, 2)}\n`);
  writeFileSync(LAYOUTS_PATH, `${JSON.stringify(layouts, null, 2)}\n`);
  console.log("\n✓ Wrote terrain-templates.json + terrain-layouts.json.");
}

main();
